const MediaViewer: React.FC = ({ evidence }) => {
  const { t } = useTranslation();
  const [dimensions, setDimensions] = useState<{ width: number; height: number } | null>(null);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  const mediaUrl = evidence.img_url || (evidence.metadata as Record)?.url;

  useEffect(() => {
    if (evidence.evidence_type !== 'image' || !mediaUrl) return;

    let isMounted = true;
    setIsImageLoaded(false);
    setDimensions(null);

    const img = new Image();
    img.src = mediaUrl;

    img.onload = () => {
      if (isMounted) {
        setDimensions({ width: img.naturalWidth, height: img.naturalHeight });
      }
    };
    img.onerror = () => {
      if (isMounted) {
        setDimensions({ width: 16, height: 9 });
      }
    };

    return () => {
      isMounted = false;
    };
  }, [mediaUrl, evidence.evidence_type]);

  if (!mediaUrl) {
    return (


        {t('pages.gameRoom.evidence.viewers.media.noMediaFound')}

    );
  }

  const containerStyle = dimensions
    ? { aspectRatio: `${dimensions.width} / ${dimensions.height}` }
    : { minHeight: '300px' };

  return (


      {evidence.evidence_type === 'image' ? (


          {!isImageLoaded && 
}

