            style={{
              opacity: isImageLoaded ? 1 : 0,
            }}
          />

      ) : (






            {t('pages.gameRoom.evidence.viewers.media.audioNotSupported')}


      )}




{evidence.title}
        {evidence.description && (

{evidence.description}
        )}


  );
};

